WITH valid AS (SELECT id, device_code, reading_ts, temp_c, humidity, pressure, humidity + temp_c AS humidity_plus_temp_c FROM device_readings WHERE firmware <> '2.0.1') SELECT device_code, DATE_TRUNC('HOUR', reading_ts) AS hour_window, DATE_TRUNC('DAY', reading_ts) AS activity_day, ROUND(AVG(temp_c), 2) AS avg_temp_c, ROUND(SUM(pressure) / NULLIF(COUNT(CASE WHEN device_code = 'DV-02' THEN 1 END), 0), 2) AS pressure_per_dv_02, STDDEV_SAMP(humidity) AS humidity_stddev, ROUND(AVG(temp_c), 2) AS avg_temp_c_2, PERCENTILE_APPROX(pressure, ARRAY(0.25, 0.5, 0.75)) AS pressure_quartiles FROM valid GROUP BY device_code, DATE_TRUNC('HOUR', reading_ts), DATE_TRUNC('DAY', reading_ts) ORDER BY hour_window DESC;
